sp_widget.client_script:
api.controller = function () {
    var c = this;
    c.caseUrl = function (record) {
        return '?id=form&table=x_sln_store_suppli_supply_case&sys_id=' + record.sys_id;
    };
    c.taskUrl = function (record) {
        return '?id=form&table=x_sln_store_suppli_supplier_task&sys_id=' + record.sys_id;
    };
    c.producerUrl = function (sysId) {
        return '?id=sc_cat_item&sys_id=' + sysId;
    };
};

sp_widget.css:
$navy: #17365d;
$orange: #c94f00;
$cream: #fff8f1;

.sss-shell { color: #1f2937; padding: 24px 0 48px; }
.sss-hero { background: $navy; color: #fff; border-radius: 16px; padding: 32px; box-shadow: 0 8px 24px rgba(23,54,93,.18); }
.sss-brand { color: #ff8a3d; font-weight: 800; letter-spacing: .18em; font-size: 14px; }
.sss-eyebrow { margin: 10px 0 0; font-weight: 700; }
.sss-hero h1 { color: #fff; margin: 8px 0; font-size: 32px; }
.sss-actions { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 24px; }
.sss-primary, .sss-primary:hover, .sss-primary:focus { background: #fff; color: $navy; border: 2px solid #fff; font-weight: 700; }
.sss-secondary, .sss-secondary:hover, .sss-secondary:focus { background: transparent; color: #fff; border: 2px solid #fff; font-weight: 700; }
.sss-panel { background: #fff; border: 1px solid #d8dee8; border-top: 5px solid $orange; border-radius: 10px; padding: 24px; margin-top: 24px; }
.sss-panel h2 { color: $navy; margin-top: 0; }
.sss-list { list-style: none; margin: 0; padding: 0; }
.sss-list li { display: flex; justify-content: space-between; gap: 16px; padding: 12px 0; border-bottom: 1px solid #e5e7eb; }
.sss-list a, .sss-panel a { color: #075b9a; text-decoration: underline; }
.sss-list a:focus, .sss-panel a:focus, .sss-actions a:focus { outline: 3px solid #ffbf47; outline-offset: 3px; }
@media (max-width: 767px) { .sss-hero { padding: 24px; } .sss-list li { display: block; } }

sp_widget.script:
(function () {
    data.audience = options.audience || (gs.hasRole('x_sln_store_suppli.supplier_agent') ? 'supplier' : 'internal');
    data.userName = gs.getUserDisplayName();
    data.cases = [];
    data.tasks = [];
    data.knowledge = [];

    function producer(name) {
        var item = new GlideRecord('sc_cat_item_producer');
        item.addQuery('name', name);
        item.addQuery('active', true);
        item.setLimit(1);
        item.query();
        return item.next() ? item.getUniqueValue() : '';
    }

    data.requestProducer = producer('Submit Store Supply Request');
    data.issueProducer = producer('Report Store Supply Issue');

    var cases = new GlideRecord('x_sln_store_suppli_supply_case');
    cases.addQuery('supply_state', 'NOT IN', 'closed,cancelled');
    cases.orderByDesc('sys_updated_on');
    cases.setLimit(20);
    cases.query();
    while (cases.next()) {
        if (!cases.canRead()) continue;
        data.cases.push({
            sys_id: cases.getUniqueValue(),
            number: cases.getDisplayValue('number'),
            short_description: cases.getDisplayValue('short_description'),
            store: cases.getDisplayValue('store'),
            state: cases.getDisplayValue('supply_state'),
            priority: cases.getDisplayValue('priority'),
            updated: cases.getDisplayValue('sys_updated_on'),
        });
    }

    if (data.audience === 'supplier') {
        var tasks = new GlideRecord('x_sln_store_suppli_supplier_task');
        tasks.addQuery('released', true);
        tasks.addQuery('task_state', 'NOT IN', 'complete,cancelled');
        tasks.orderByDesc('sys_updated_on');
        tasks.setLimit(20);
        tasks.query();
        while (tasks.next()) {
            if (!tasks.canRead()) continue;
            data.tasks.push({
                sys_id: tasks.getUniqueValue(),
                number: tasks.getDisplayValue('number'),
                short_description: tasks.getDisplayValue('short_description'),
                state: tasks.getDisplayValue('task_state'),
                released: tasks.getDisplayValue('released_on'),
            });
        }
    }

    var knowledge = new GlideRecord('kb_knowledge');
    knowledge.addQuery('workflow_state', 'published');
    knowledge.addQuery('short_description', 'LIKE', 'supply');
    knowledge.orderByDesc('sys_view_count');
    knowledge.setLimit(5);
    knowledge.query();
    while (knowledge.next()) {
        if (!knowledge.canRead()) continue;
        data.knowledge.push({ sys_id: knowledge.getUniqueValue(), number: knowledge.getDisplayValue('number'), title: knowledge.getDisplayValue('short_description') });
    }
})();
